-- 1) 四级词库补全（仅看四级词库内是否已有）
INSERT INTO vocabulary (word, phonetic, translation, part_of_speech, bank, create_time, teacher_id)
SELECT s.word, s.phonetic, s.translation, s.pos, '四级词库', NOW(), 1
FROM cet4_seed s
WHERE NOT EXISTS (SELECT 1 FROM vocabulary v WHERE v.bank = '四级词库' AND LOWER(TRIM(v.word)) = s.word);

-- 2) 六级词库补全（CET6 去重 CET4 后，仅看六级词库内是否已有）
INSERT INTO vocabulary (word, phonetic, translation, part_of_speech, bank, create_time, teacher_id)
SELECT s.word, s.phonetic, s.translation, s.pos, '六级词库', NOW(), 1
FROM cet6_seed s
WHERE NOT EXISTS (SELECT 1 FROM vocabulary v WHERE v.bank = '六级词库' AND LOWER(TRIM(v.word)) = s.word);

-- 3) 可选：把 CET4 词从六级词库里移除，让六级词库恰好 = CET6 去重四级（约 1956）。
--    确认要执行再取消下面两行注释；若六级库存有手工添加的词，请谨慎。
-- DELETE v FROM vocabulary v JOIN cet4_seed s ON LOWER(TRIM(v.word)) = s.word WHERE v.bank = '六级词库';

SELECT bank, COUNT(*) AS total FROM vocabulary WHERE bank IN ('四级词库','六级词库') GROUP BY bank;
DROP TEMPORARY TABLE cet4_seed;
DROP TEMPORARY TABLE cet6_seed;
